BEGIN;
CREATE TABLE t_question_backup_20261118_lane1e AS SELECT * FROM t_question WHERE id IN (389090,389984,390502);
CREATE TABLE t_text_content_backup_20261118_lane1e AS SELECT * FROM t_text_content WHERE id IN (389363,390266,390792);
CREATE TEMP TABLE img_expected(id integer PRIMARY KEY, tc_id integer NOT NULL, content text NOT NULL) ON COMMIT DROP;
INSERT INTO img_expected VALUES
(389090,389363,$q${"titleContent": "在 Excel 2003 工作表中,已输入的数据如下图所示。若选中 D1 单元格,利用填充柄向下拖动到 D2 单元格,则 D2 单元格的值为 ____。<br/><img src=\"/qimg/q389090.jpg\"/>", "analyze": "选中 D1 单元格,利用填充柄向下拖动到 D2 单元格,将会实现 D1 单元格中的公式复制到 D2 单元格的效果。在复制公式的时候,遵循“相对地址引用随着目标单元格的变化而变化,绝对地址引用不变”的原则。D1 中的公式“$= A \\$1 * C1$”复制到 D2,目标单元格“行向下一行,列未变”,即“$A \\$1$”不变,“C1”变为“C2”,D2 中的公式为“$= A \\$1 * C2$”。带入数值,即“$20 * 20\\%$”,结果为数值“4”。因此,本题选 B。", "correct": null, "questionItemObjects": [{"prefix": "A", "content": "2", "itemUuid": "06eb5813a8a54b36a2fc3c268a8e8619", "score": null}, {"prefix": "B", "content": "4", "itemUuid": "b41fadf8960b478ebee8f3a255b1f47c", "score": null}, {"prefix": "C", "content": "6", "itemUuid": "eaa0d88ed2294c3093703e3a9e238c28", "score": null}, {"prefix": "D", "content": "<br/>| | A | B | C | D |<br/>| --- | --- | --- | --- | --- |<br/>| 1 | 20 | 20 | 10% | =$A$1*Cl |<br/>| 2 | 30 | 40 | 20% | |", "itemUuid": "c45fa5950bad4ef7a869852e0c494f22", "score": null}]}$q$),
(389984,390266,$q${"titleContent": "在 Excel 中, 如题 79 图所示, 若将 A6 单元格的公式复制到 B6 单元格, 则 B6 单元格的值是 ____; 若将 A6 单元格的公式剪切到 C6 单元格, 则 C6 单元格的值是 ____。<br/><br/>&lt;table&gt;&lt;tr&gt;&lt;td&gt;&lt;/td&gt;&lt;td&gt;A&lt;/td&gt;&lt;td&gt;B&lt;/td&gt;&lt;td&gt;C&lt;/td&gt;&lt;td&gt;D&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;1&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;td&gt;9&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;td&gt;12&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;13&lt;/td&gt;&lt;td&gt;14&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;td&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;6&lt;/td&gt;&lt;td colspa<br/><img src=\"/qimg/q389984.jpg\"/>", "analyze": "第1空: AVERAGE函数的功能是求各参数的算术平均值。在Excel中, 复制公式的时候, 遵循“相对地址引用随着目标单元格的变化而变化, 绝对地址引用不变”的原则。A6中的公式“=AVERAGE(A1:A5)”复制到B6, 目标单元格“行不变, 列向右一列”, 即“A1”变为“B1”, “A5”变为“B5”, 公式变为“=AVERAGE(B1:B5)”, 计算结果为“8”。第2空: 在Excel中, 移动公式的时候, 公式不发生改变, 即公式仍为“=AVERAGE(A1:A5)”, 计算结果为“7”。因此, 本题填“8”、“7”。", "correct": null, "questionItemObjects": [{"prefix": "1", "content": "8", "itemUuid": "1cc7847a19e14d7dbe846edaa635f04f", "score": null}, {"prefix": "2", "content": "7", "itemUuid": "c601305a15064ca08f7ca5ce626d6a04", "score": null}]}$q$),
(390502,390792,$q${"titleContent": "右键单击 Windows 10 的桌面空白处，在弹出的菜单中选 “显示设置” 结果如题 37 图所示。通过选择____可以查看计算机存储空间的使用情况和可用情况。<br/><img src=\"/qimg/q390502.jpg\"/>", "analyze": "为了重新排列 Windows 10 桌面上的图标，可右键单击桌面空白处，在弹出的菜单中选择排序方式。", "correct": null, "questionItemObjects": [{"prefix": "1", "content": "存储", "itemUuid": "f2d02434b91f4fb3b6290cc630221ca6", "score": null}]}$q$);
UPDATE t_text_content t SET content=e.content FROM img_expected e WHERE t.id=e.tc_id;
UPDATE t_question q SET has_image=true FROM img_expected e WHERE q.id=e.id AND NOT q.is_golden;
DO $$ DECLARE n int; BEGIN
 SELECT count(*) INTO n FROM t_question q JOIN img_expected e ON e.id=q.id WHERE q.has_image; IF n<>3 THEN RAISE EXCEPTION 'has_image'; END IF;
 SELECT count(*) INTO n FROM t_text_content t JOIN img_expected e ON e.tc_id=t.id WHERE t.content=e.content AND pg_input_is_valid(t.content,'json'); IF n<>3 THEN RAISE EXCEPTION 'content'; END IF;
END $$;
COMMIT;
